package shortnumber

import (
	"regexp"
	"sync"
)

// metadata_gen.go is generated by a go:generate directive in the module
// root's metadata.go, alongside the other metadata.

// territory is one region's short numbers. Field meanings follow upstream's
// phonemetadata.proto.
type territory struct {
	id string

	// generalDesc matches every short number in the region, and its
	// lengths are those of shortCode.
	generalDesc numberDesc
	// shortCode matches the valid short numbers. The other descriptions
	// are categories within it.
	shortCode       numberDesc
	tollFree        numberDesc
	standardRate    numberDesc
	premiumRate     numberDesc
	emergency       numberDesc
	carrierSpecific numberDesc
	smsServices     numberDesc
}

// numberDesc describes one category of short numbers.
type numberDesc struct {
	pattern *pattern
	example string
	// lengths lists the possible lengths of a number. An empty list means
	// "the same as the general description", and the list [-1] means the
	// region has no numbers in this category.
	lengths []int8
}

// matches reports whether nsn has a possible length for d and matches its
// pattern.
func (d *numberDesc) matches(nsn string) bool {
	if len(d.lengths) > 0 && !hasLength(d.lengths, len(nsn)) {
		return false
	}
	return d.pattern != nil && d.pattern.matchFull(nsn)
}

// hasLength reports whether lengths contains n.
func hasLength(lengths []int8, n int) bool {
	for _, l := range lengths {
		if int(l) == n {
			return true
		}
	}
	return false
}

// pattern is a metadata regular expression, compiled on first use.
type pattern struct {
	expr string

	fullOnce, prefixOnce sync.Once
	full, prefix         *regexp.Regexp
}

// matchFull reports whether the expression matches all of s.
func (p *pattern) matchFull(s string) bool {
	p.fullOnce.Do(func() { p.full = regexp.MustCompile(`^(?:` + p.expr + `)$`) })
	return p.full.MatchString(s)
}

// matchPrefix reports whether the expression matches a prefix of s.
func (p *pattern) matchPrefix(s string) bool {
	p.prefixOnce.Do(func() { p.prefix = regexp.MustCompile(`^(?:` + p.expr + `)`) })
	return p.prefix.MatchString(s)
}

// regions indexes territoryData by region code.
var regions = sync.OnceValue(func() map[string]*territory {
	m := make(map[string]*territory, len(territoryData))
	for _, t := range territoryData {
		m[t.id] = t
	}
	return m
})
